SELECT TRUNC(s.SNAPSHOT_MONTH,'MM') SNAPSHOT_MONTH, a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, o.ORG_TYPE_CODE, s.LOAN_STATUS, COUNT(*) LOAN_COUNT, SUM(s.OUTSTANDING_PRINCIPAL) OUTSTANDING_PRINCIPAL, SUM(s.OVERDUE_AMOUNT) OVERDUE_AMOUNT, SUM(s.SUBSIDY_BALANCE) SUBSIDY_BALANCE, SUM(CASE WHEN s.DAYS_PAST_DUE > 0 THEN 1 ELSE 0 END) DELINQUENT_LOAN_COUNT FROM MFF_LOAN_MONTHLY_SNAPSHOT s JOIN MFF_LOANS l ON l.LOAN_ID=s.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=l.APPLICATION_ID JOIN MFF_ORGANIZATIONS o ON o.ORG_ID=a.FINANCIER_ID GROUP BY TRUNC(s.SNAPSHOT_MONTH,'MM'),a.FINANCIER_ID,o.ORG_NAME_AR,o.ORG_TYPE_CODE,s.LOAN_STATUS;
